// Experimental fixed NG256/GS8/NCOL3/S_RD2 stage partition. NOT adopted or physically qualified.
// Eight actual clocks, no parent registers, no added data edge. Parent wires join actual registered leaf ports.
// Requires a new exact pin/clock/reset contract before any physical gate. Do not substitute for current production module.
module ot_s81_hc_ctfn_input_c0(input wire clk, rst_in, input wire [6:0] fv_in, input wire [63:0] d, output reg [63:0] q, output reg [6:0] fv, (* keep = "true" *) output reg [3:0] ysel, output wire rst_c,rst_n);
reg [1:0] rr; always @(posedge clk) rr <= {rr[0],rst_in};
assign rst_c=rr[0]; assign rst_n=rr[1];
always @(posedge clk or negedge rst_n) if(!rst_n) begin fv<=0;ysel<=0;end else begin fv<=fv_in;ysel<={4{fv_in[2]}};end
always @(posedge clk) q<=d;
endmodule
